You are implementing Task 3.4: Star Map (Canvas)

## Task Description

Build the interactive star map at `app/starmap/page.tsx` using HTML5 Canvas.

IMPORTANT: Import animations from `motion/react`, NOT from `framer-motion`.
IMPORTANT: Use `clsx` for className composition.

### Implementation

**Files to create:**
- `app/starmap/page.tsx` — page wrapper
- `components/game/StarMap.tsx` — Canvas component

### StarMap.tsx — Canvas Component

A full-viewport Canvas that renders:

1. **3-layer parallax starfield** (same as StarfieldBackground but rendered directly on this canvas)

2. **8 planets** as glowing circles:
   - Position from `planets` data (normalized 0-100 → canvas pixel coords)
   - Size: ~30-40px radius
   - Color from planet data

3. **Planet visual states** based on game state:
   - **Locked**: dim gray circle, 30% opacity, no animation
   - **Available**: pulsing glow in planet color (sine wave opacity animation)
   - **In Progress**: solid circle + partial glowing ring (arc based on missions completed/total)
   - **Completed**: full bright circle + complete glowing ring + small checkmark

4. **Connection lines** between planets following the prerequisite chain:
   - Dim dashed line for locked connections
   - Solid glowing line for available/completed connections

5. **Planet name labels** below each planet (white text, small font)

6. **Academy space station** at top center — always available, distinct shape (rectangle/diamond instead of circle)

7. **Click/tap handling**:
   - Hit detection: check if click is within planet radius
   - If available/in-progress: navigate to `/planets/[planetId]`
   - If locked: show a toast/tooltip "Complete [prerequisite planet] first"
   - Academy always navigable

8. **Act region labels**: subtle text labels "ACT 1", "ACT 2", "ACT 3" in their regions

### Planet positions (normalized 0-100, map to canvas):
```
Act 1 (center-right, warm):
  Vibe World: (30, 60)
  Debt Belt: (55, 50)

Act 2 (left-center, cool):
  MCP Station: (20, 35)
  Agent Academy: (50, 28)
  Framework Nebula: (78, 35)

Act 3 (top, dramatic):
  Orchestration Citadel: (25, 15)
  Security Fortress: (55, 12)
  Production Worlds: (80, 15)

Academy Station: (50, 5) — always at top center
```

### Key imports:
```tsx
import { useGame } from '@/lib/game-context'
import { planets, MISSION_COUNTS } from '@/lib/data/planets'
import { getPlanetStatus } from '@/lib/game-state'
```

### Canvas rendering approach:
```tsx
'use client'

import { useRef, useEffect, useCallback } from 'react'
import { useRouter } from 'next/navigation'
import { useGame } from '@/lib/game-context'
import { planets, MISSION_COUNTS } from '@/lib/data/planets'
import { getPlanetStatus } from '@/lib/game-state'

interface StarMapProps {
  className?: string
}

export function StarMap({ className }: StarMapProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const { state } = useGame()
  const router = useRouter()
  const animFrameRef = useRef<number>(0)
  const timeRef = useRef(0)

  // Convert normalized (0-100) to canvas coords
  const toCanvas = useCallback((x: number, y: number, width: number, height: number) => {
    const padding = 60 // edge padding
    return {
      cx: padding + (x / 100) * (width - padding * 2),
      cy: padding + (y / 100) * (height - padding * 2),
    }
  }, [])

  // Main render loop
  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas || !state) return
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    const resize = () => {
      canvas.width = window.innerWidth
      canvas.height = window.innerHeight
    }
    resize()
    window.addEventListener('resize', resize)

    // Stars for background
    const stars = Array.from({ length: 150 }, () => ({
      x: Math.random() * canvas.width,
      y: Math.random() * canvas.height,
      size: Math.random() * 1.5 + 0.5,
      opacity: Math.random() * 0.5 + 0.1,
      speed: Math.random() * 0.2 + 0.05,
    }))

    const render = () => {
      timeRef.current += 0.016 // ~60fps
      const t = timeRef.current
      ctx.clearRect(0, 0, canvas.width, canvas.height)
      ctx.fillStyle = '#0a0f1a'
      ctx.fillRect(0, 0, canvas.width, canvas.height)

      // Draw stars
      for (const star of stars) {
        star.y += star.speed
        if (star.y > canvas.height) { star.y = 0; star.x = Math.random() * canvas.width }
        ctx.beginPath()
        ctx.arc(star.x, star.y, star.size, 0, Math.PI * 2)
        ctx.fillStyle = `rgba(232, 224, 212, ${star.opacity})`
        ctx.fill()
      }

      // Draw connection lines between planets
      for (const planet of planets) {
        const status = getPlanetStatus(planet.id as any, state, MISSION_COUNTS as any)
        const { cx, cy } = toCanvas(planet.position.x, planet.position.y, canvas.width, canvas.height)

        for (const prereqId of planet.prerequisites) {
          const prereq = planets.find(p => p.id === prereqId)
          if (!prereq) continue
          const { cx: px, cy: py } = toCanvas(prereq.position.x, prereq.position.y, canvas.width, canvas.height)

          ctx.beginPath()
          ctx.moveTo(px, py)
          ctx.lineTo(cx, cy)
          if (status === 'locked') {
            ctx.strokeStyle = 'rgba(232, 224, 212, 0.1)'
            ctx.setLineDash([5, 10])
          } else {
            ctx.strokeStyle = 'rgba(232, 224, 212, 0.3)'
            ctx.setLineDash([])
          }
          ctx.lineWidth = 1
          ctx.stroke()
          ctx.setLineDash([])
        }
      }

      // Draw planets
      for (const planet of planets) {
        const status = getPlanetStatus(planet.id as any, state, MISSION_COUNTS as any)
        const { cx, cy } = toCanvas(planet.position.x, planet.position.y, canvas.width, canvas.height)
        const radius = 22

        // Planet circle
        ctx.beginPath()
        ctx.arc(cx, cy, radius, 0, Math.PI * 2)

        if (status === 'locked') {
          ctx.fillStyle = 'rgba(100, 100, 100, 0.3)'
        } else if (status === 'available') {
          const pulse = 0.5 + Math.sin(t * 2) * 0.3
          ctx.fillStyle = planet.color
          ctx.globalAlpha = pulse
          // Glow
          ctx.shadowColor = planet.color
          ctx.shadowBlur = 20
        } else if (status === 'in_progress') {
          ctx.fillStyle = planet.color
          ctx.globalAlpha = 0.8
          ctx.shadowColor = planet.color
          ctx.shadowBlur = 15
        } else { // completed
          ctx.fillStyle = planet.color
          ctx.globalAlpha = 1
          ctx.shadowColor = planet.color
          ctx.shadowBlur = 25
        }
        ctx.fill()
        ctx.globalAlpha = 1
        ctx.shadowBlur = 0

        // Orbital ring for in_progress/completed
        if (status === 'in_progress' || status === 'completed') {
          ctx.beginPath()
          const endAngle = status === 'completed' ? Math.PI * 2 : Math.PI * 2 * 0.5 // simplified
          ctx.arc(cx, cy, radius + 6, -Math.PI / 2, -Math.PI / 2 + endAngle)
          ctx.strokeStyle = planet.color
          ctx.lineWidth = 2
          ctx.stroke()
        }

        // Planet name
        ctx.font = '12px Inter, sans-serif'
        ctx.fillStyle = status === 'locked' ? 'rgba(232, 224, 212, 0.3)' : 'rgba(232, 224, 212, 0.8)'
        ctx.textAlign = 'center'
        ctx.fillText(planet.name, cx, cy + radius + 20)
      }

      // Academy station at top
      const { cx: acx, cy: acy } = toCanvas(50, 5, canvas.width, canvas.height)
      ctx.beginPath()
      // Diamond shape for academy
      ctx.moveTo(acx, acy - 18)
      ctx.lineTo(acx + 18, acy)
      ctx.lineTo(acx, acy + 18)
      ctx.lineTo(acx - 18, acy)
      ctx.closePath()
      ctx.fillStyle = '#4a6fa5'
      ctx.shadowColor = '#4a6fa5'
      ctx.shadowBlur = 15
      ctx.fill()
      ctx.shadowBlur = 0
      ctx.font = '12px Inter, sans-serif'
      ctx.fillStyle = 'rgba(232, 224, 212, 0.8)'
      ctx.textAlign = 'center'
      ctx.fillText('THE ACADEMY', acx, acy + 35)

      animFrameRef.current = requestAnimationFrame(render)
    }

    render()

    return () => {
      cancelAnimationFrame(animFrameRef.current)
      window.removeEventListener('resize', resize)
    }
  }, [state, toCanvas])

  // Click handler
  const handleClick = useCallback((e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current
    if (!canvas || !state) return
    const rect = canvas.getBoundingClientRect()
    const clickX = e.clientX - rect.left
    const clickY = e.clientY - rect.top

    // Check academy click
    const { cx: acx, cy: acy } = toCanvas(50, 5, canvas.width, canvas.height)
    if (Math.abs(clickX - acx) < 25 && Math.abs(clickY - acy) < 25) {
      router.push('/academy')
      return
    }

    // Check planet clicks
    for (const planet of planets) {
      const { cx, cy } = toCanvas(planet.position.x, planet.position.y, canvas.width, canvas.height)
      const dist = Math.sqrt((clickX - cx) ** 2 + (clickY - cy) ** 2)
      if (dist < 30) {
        const status = getPlanetStatus(planet.id as any, state, MISSION_COUNTS as any)
        if (status === 'locked') {
          // Could show a toast — for now just return
          return
        }
        router.push(`/planets/${planet.id}`)
        return
      }
    }
  }, [state, router, toCanvas])

  return (
    <canvas
      ref={canvasRef}
      onClick={handleClick}
      className={clsx('fixed inset-0 cursor-pointer', className)}
    />
  )
}
```

